	.stamp {
		position: absolute;
		top: 8px;
		left: 8px;
		width: 24px;
		height: 24px;
		display: flex;
		align-items: center;
		justify-content: center;
		font-size: 14px;
		font-weight: 700;
		line-height: 1;
		border-radius: 50%;
		color: #0a0b0f;
		background: var(--ok);
		box-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
	}

	.done-pill {
		font-size: 11px;
		font-weight: 700;
		letter-spacing: 0.04em;
		text-transform: uppercase;
		padding: 3px 9px;
		border-radius: 999px;
		color: var(--ok);
		background: color-mix(in srgb, var(--ok) 16%, transparent);
		border: 1px solid color-mix(in srgb, var(--ok) 45%, transparent);
		white-space: nowrap;
	}

	.big-question {
		font-size: 17px;
		font-weight: 600;
		line-height: 1.4;
		color: var(--text);
	}

	.predict {
		padding: 18px 16px;
		display: flex;
		flex-direction: column;
		gap: 18px;
	}

	.predict .big-question {
		margin: 0;
		font-size: 22px;
		font-weight: 700;
		line-height: 1.3;
	}

	.prompt {
		margin: 0;
		font-size: 15px;
		color: var(--text-dim);
	}

	/* Stacked, not side by side: the choices are sentences, and three columns of
     a 740 px dialog can't hold one without ragged wrapping. Stacked they also
     read as the radio list they behave like. */
	.choices {
		display: flex;
		flex-direction: column;
		gap: 10px;
	}

	.choice {
		display: flex;
		align-items: center;
		gap: 14px;
		width: 100%;
		padding: 15px 16px;
		text-align: left;
		font-size: 16px;
		line-height: 1.35;
		background: var(--bg-raised);
		border: 1px solid var(--border);
		border-radius: 12px;
		transition:
			background-color 0.12s ease,
			border-color 0.12s ease;
	}

	.choice .text {
		flex: 1;
		min-width: 0;
	}

	/* A lettered badge rather than a radio ring: nothing is ever shown selected
     (picking commits and closes the step), so the marker's job is to name the
