		background: color-mix(in srgb, var(--mission-color) 30%, transparent);
		color: var(--text);
	}

	.start-note {
		margin: 0;
		font-size: 13px;
		line-height: 1.45;
		color: var(--text-dim);
	}

	/* The progress row: bar, count, and the control that resets them. Sits
