	}

	/* Armed: the click that actually clears reads as destructive. */
	.reset.confirm {
		color: var(--danger, #ff8080);
		border-color: color-mix(in srgb, var(--danger, #ff8080) 55%, var(--border));
		background: color-mix(in srgb, var(--danger, #ff8080) 14%, transparent);
	}

	.reset.confirm:hover {
		color: #0a0b0f;
		background: var(--danger, #ff8080);
		border-color: var(--danger, #ff8080);
	}

	/* --- narrow viewports -------------------------------------------------
     Two things break on a phone: the card's 150 px portrait column leaves the
     question about 160 px of a 390 px screen, and the choices row divides that
     same width three ways. Both become vertical stacks. */
	@media (max-width: 560px) {
		.backdrop {
			/* Full-bleed: a rounded card floating in a 16 px margin wastes width
         that the questions need. */
			padding: 0;
			padding-top: env(safe-area-inset-top);
			padding-bottom: env(safe-area-inset-bottom);
		}

		.dialog {
			border-radius: 0;
			border-left: none;
			border-right: none;
		}

		header {
			padding: 12px;
		}

		h2 {
			font-size: 17px;
		}

		/* The portrait moves above the text and becomes a letterbox banner, so the
       question gets the full width. */
		.card {
			flex-direction: column;
		}

		/* A fixed banner height rather than an aspect ratio: a ratio against the
       full card width resolves to ~230 px, which crowds the question off a
       phone screen. */
		.portrait {
			width: auto;
			height: 104px;
			flex: none;
		}

		.body {
			padding: 12px;
		}

		.list {
			padding: 10px;
		}

		.predict {
			padding: 14px 12px;
		}

		.predict .big-question {
			font-size: 19px;
		}

		.choice {
			gap: 12px;
			padding: 13px 14px;
			font-size: 15px;
		}

		.progress-bar {
			gap: 10px;
			padding: 10px 12px;
		}

